export function ownerF128CompletionReconstruction(components:BuildingComponent[]):{components:BuildingComponent[];stats:OwnerReconstructionStats}{const stats:OwnerReconstructionStats={objects:0,vertices:0,triangles:0,originalVertices:0,sourceRetained:true,actualVisualAccepted:false,components:[]};const found=components.filter(c=>c.city==='cologne'&&c.objectId===SOURCE.objectId);if(!found.length)return{components,stats};const c=found[0];const valid=found.length===1&&c.partId===SOURCE.partId&&nativePaintSignature(c)===SOURCE.geometrySignature&&JSON.stringify(c.origin)===JSON.stringify(SOURCE.origin)&&JSON.stringify(c.componentGeometry)===JSON.stringify(SOURCE.componentGeometry)&&JSON.stringify(c.sourceFeature)===JSON.stringify(SOURCE.sourceFeature)&&c.batches.length===SOURCE.batches.length&&c.batches.every((b,bi)=>['positions','normals','indices','color'].every(k=>{const x=(b as any)[k],y=(SOURCE.batches[bi]as any)[k];return x.length===y.length&&Array.from(x as ArrayLike<number>).every((v,j)=>Object.is(v,y[j]));}))&&JSON.stringify((PROGRESSIVE_ADMISSIONS as readonly any[]).filter(r=>r.city==='cologne'&&r.objectId===SOURCE.objectId))===JSON.stringify(ADMISSIONS);if(!valid){stats.error='F128 SOURCE/accepted4883 guard failed; roof-only input retained';return{components,stats};}const batches=DISPLAY.batches.map(b=>({...b,positions:new Float32Array(b.positions),normals:new Float32Array(b.normals),indices:new Uint32Array(b.indices)}));const vertices=batches.reduce((n,b)=>n+b.positions.length/3,0),triangles=batches.reduce((n,b)=>n+b.indices.length/3,0);stats.objects=1;stats.vertices=vertices;stats.triangles=triangles;stats.originalVertices=130;stats.components=[{objectId:c.objectId,partId:c.partId,sourcePartId:c.partId,patchSHA256:F128_COMPLETION_SHA,vertices,triangles,geometryRole:'owner-authorized-reconstruction'}];return{components:components.map(x=>x===c?{...c,batches,displayEstimates:{...c.displayEstimates,F128Completion:{patchSHA256:F128_COMPLETION_SHA,sourceRetained:true,accepted4883Original12PaintFramePreserved:true,roof6405Original26PaintFramePreserved:true,displayMainHeight24PhotoEstimate:true,displaySteppedAdministrativeWing:true,legacy4883VirtualYScale10Div24:true,actualVisualAccepted:false}}}as unknown as BuildingComponent:x),stats};}
export function ownerF128CompletionMaterials(components:BuildingComponent[],paint:Float32Array,frames:Float32Array){let offset=0;for(const c of components){const ok=c.city==='cologne'&&ownerF128CompletionIdentity(c)&&!!c.displayEstimates?.F128Completion;let local=0;for(const b of c.batches){const n=b.positions.length/3;if(ok)for(let j=0;j<n;j++){if(![6406,6405,4883].includes(DISPLAY.frames[(local+j)*5+4]))continue;paint.set(DISPLAY.paint.slice((local+j)*4,(local+j+1)*4),(offset+j)*4);frames.set(DISPLAY.frames.slice((local+j)*5,(local+j+1)*5),(offset+j)*5);}offset+=n;local+=n;}}}
